persistedQueries.adventure-by-path:
# Get an adventure by path.
#
# Required query variables:
# - { "adventurePath": "/content/dam/wknd-shared/en/adventures/bali-surf-camp/bali-surf-camp" }
#
# Optional query variables:
# - { 
#     "imageFormat": "JPG",
#     "imageSeoName": "my-adventure",
#     "imageWidth": 1600,
#     "imageQuality": 90 
#   }

query getAdventureByPath($adventurePath: String!, $imageFormat: AssetTransformFormat=JPG, $imageSeoName: String, $imageWidth: Int=1200, $imageQuality: Int=80) {
  adventureByPath(_path: $adventurePath, _assetTransform: {
    format: $imageFormat
    seoName: $imageSeoName
    width: $imageWidth
    quality: $imageQuality
    preferWebp: true
  }) {
    item {
      _path
      title
      slug
      description {
        json
        plaintext
        html
      }
      adventureType
      tripLength
      activity
      groupSize
      difficulty
      price
      primaryImage {
        ... on ImageRef {
          _path
          _dynamicUrl
        }
      }
      itinerary {
        json
        plaintext
        html
      }
    }
  }
}

persistedQueries.adventure-by-price:
# Retrieves an Adventure Fragment based on a given price and operator
#
# Required query variables:
#  - { "price": 1200, "priceOperator": "LOWER" } or {"price": 1200, "priceOperator": "GREATER_EQUAL" }
# 
# Optional query variables:
# - { 
#     "imageFormat": "JPG",
#     "imageWidth": 1600,
#     "imageQuality": 90 
#   }

query filterAdventuresByPrice($price: Float!, $priceOperator: FloatOperator!, $imageFormat: AssetTransformFormat=JPG, $imageWidth: Int=1200, $imageQuality: Int=80) {
  adventureList(
    sort: "price ASC"
    filter: {price: {_expressions: [{value: $price, _operator: $priceOperator}]}}
    _assetTransform: {
      format: $imageFormat
      width: $imageWidth
      quality: $imageQuality
      preferWebp: true
  }) {
    items {
      _path
      title
      slug
      activity
      adventureType
      price
      tripLength
      groupSize
      difficulty
      price
      primaryImage {
        ... on ImageRef {
          _path
          _dynamicUrl
        }
      }
      description {
        json
        plaintext
        html
      }
      itinerary {
        json
        plaintext
        html
      }
    }
  }
}

persistedQueries.adventure-by-slug:
# Retrieves an Adventure Fragment based on it's unique slug.
#
# Required query variables:
# - {"slug": "bali-surf-camp"}
#
# Optional query variables:
# - { 
#     "imageFormat": "JPG",
#     "imageSeoName": "my-adventure",
#     "imageWidth": 1600,
#     "imageQuality": 90 
#   }
#  
# This query returns an adventure list but since the the slug property is set to be unique in the Content Fragment Model, only a single Content Fragment is expected.

query ($slug: String!, $imageFormat:AssetTransformFormat=JPG, $imageSeoName: String, $imageWidth: Int=1200, $imageQuality: Int=80) {
  adventureList(
    filter: {slug: {_expressions: [{value: $slug}]}}
    _assetTransform: {
      format: $imageFormat
      seoName: $imageSeoName
      width: $imageWidth
      quality: $imageQuality
      preferWebp: true
  }) {
    items {
      _path
      title
      slug
      activity
      adventureType
      price
      tripLength
      groupSize
      difficulty
      price
      primaryImage {
        ... on ImageRef {
          _path
          _dynamicUrl
        }
      }
      description {
        json
        plaintext
        html
      }
      itinerary {
        json
        plaintext
        html
      }
    }
    _references {
      ... on AdventureModel {
        _path
        slug
        title
        price
        __typename
      }
    }
  }
}

